-- =============================================================================
-- SIPAKAR RSUD KARDINAH: MIGRATION & POPULATE MASTER BARANG BMD
-- Sumber Data: Permendagri No. 108 Tahun 2016 (Lengkap Level 5, 6, dan 7)
-- Total Item: 13.476 Barang Fisik (Level 7) + Kategori Level 5 & Level 6
-- Target Engine: MySQL 8.0 / 8.4+
-- =============================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- 1. DDL: MEMASTIKAN TABEL DAN STRUKTUR KOLOM MASTER_BARANGS TERSEDIA LENGKAP
CREATE TABLE IF NOT EXISTS `master_barangs` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `kode_barang` VARCHAR(100) NOT NULL UNIQUE COMMENT 'Kode identitas unik barang di SIPAKAR',
  `kode_permendagri` VARCHAR(50) DEFAULT NULL COMMENT 'Kodefikasi Level 7 Permendagri No. 108 Tahun 2016',
  `kode_level5` VARCHAR(20) DEFAULT NULL COMMENT 'Kode Rincian Objek (Level 5)',
  `nama_level5` VARCHAR(255) DEFAULT NULL COMMENT 'Nama Rincian Objek (Level 5)',
  `kode_level6` VARCHAR(30) DEFAULT NULL COMMENT 'Kode Sub Rincian Objek (Level 6)',
  `nama_level6` VARCHAR(255) DEFAULT NULL COMMENT 'Nama Sub Rincian Objek (Level 6)',
  `nama_barang` VARCHAR(255) NOT NULL COMMENT 'Nama/Uraian barang (Level 7)',
  `satuan` VARCHAR(50) DEFAULT 'Unit' COMMENT 'Satuan default pemesanan',
  `deskripsi` TEXT DEFAULT NULL COMMENT 'Hierarki kategori resmi bebas typo',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1 COMMENT 'Status aktif',
  `created_by` BIGINT UNSIGNED DEFAULT NULL,
  `updated_by` BIGINT UNSIGNED DEFAULT NULL,
  `deleted_by` BIGINT UNSIGNED DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` TIMESTAMP NULL DEFAULT NULL,
  INDEX `idx_master_barangs_kode_permendagri` (`kode_permendagri`),
  INDEX `idx_master_barangs_kode_level5` (`kode_level5`),
  INDEX `idx_master_barangs_nama_level5` (`nama_level5`),
  INDEX `idx_master_barangs_kode_level6` (`kode_level6`),
  INDEX `idx_master_barangs_level5_level6` (`kode_level5`, `kode_level6`),
  INDEX `idx_master_barangs_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. ALTER TABLE AMAN: JIKA TABEL SUDAH ADA DARI MIGRASI LAMA, TAMBAHKAN KOLOM LEVEL 5 & 6
SET @col_p = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'master_barangs' AND column_name = 'kode_permendagri');
SET @sql_p = IF(@col_p = 0, 'ALTER TABLE `master_barangs` ADD COLUMN `kode_permendagri` VARCHAR(50) DEFAULT NULL AFTER `kode_barang`, ADD INDEX `idx_master_barangs_kode_permendagri` (`kode_permendagri`);', 'SELECT 1;');
PREPARE stmt_p FROM @sql_p; EXECUTE stmt_p; DEALLOCATE PREPARE stmt_p;

SET @col_l5 = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'master_barangs' AND column_name = 'kode_level5');
SET @sql_l5 = IF(@col_l5 = 0, 'ALTER TABLE `master_barangs` ADD COLUMN `kode_level5` VARCHAR(20) DEFAULT NULL AFTER `kode_permendagri`, ADD COLUMN `nama_level5` VARCHAR(255) DEFAULT NULL AFTER `kode_level5`, ADD INDEX `idx_master_barangs_kode_level5` (`kode_level5`), ADD INDEX `idx_master_barangs_nama_level5` (`nama_level5`);', 'SELECT 1;');
PREPARE stmt_l5 FROM @sql_l5; EXECUTE stmt_l5; DEALLOCATE PREPARE stmt_l5;

SET @col_l6 = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'master_barangs' AND column_name = 'kode_level6');
SET @sql_l6 = IF(@col_l6 = 0, 'ALTER TABLE `master_barangs` ADD COLUMN `kode_level6` VARCHAR(30) DEFAULT NULL AFTER `nama_level5`, ADD COLUMN `nama_level6` VARCHAR(255) DEFAULT NULL AFTER `kode_level6`, ADD INDEX `idx_master_barangs_kode_level6` (`kode_level6`), ADD INDEX `idx_master_barangs_level5_level6` (`kode_level5`, `kode_level6`);', 'SELECT 1;');
PREPARE stmt_l6 FROM @sql_l6; EXECUTE stmt_l6; DEALLOCATE PREPARE stmt_l6;

-- 3. DML: POPULATE & UPDATE 13.476 DATA MASTER BARANG DENGAN LEVEL 5 & 6 RESMI
ON DUPLICATE KEY UPDATE `kode_permendagri`=VALUES(`kode_permendagri`), `kode_level5`=VALUES(`kode_level5`), `nama_level5`=VALUES(`nama_level5`), `kode_level6`=VALUES(`kode_level6`), `nama_level6`=VALUES(`nama_level6`), `nama_barang`=VALUES(`nama_barang`), `satuan`=VALUES(`satuan`), `deskripsi`=VALUES(`deskripsi`), `is_active`=VALUES(`is_active`), `updated_at`=NOW();

